// Registers the service worker (generated by vite.config.ts as /sw.js) that
// caches the Typst compiler, fonts and mitex package, so they download once
// (ADR 0002; for speed, not offline use). Production builds only: in
// `pnpm dev` the files are served unhashed and change under you.

/**
 * @param assetsLoaded resolves once the page has finished downloading the
 *   Typst files itself; only then is the service worker asked to cache them,
 *   so a first visit never downloads them twice at once.
 */
export function registerServiceWorker(assetsLoaded: Promise<void>): void {
  if (!import.meta.env.PROD) return;
  if (!("serviceWorker" in navigator)) return;
  if (location.protocol !== "https:" && location.hostname !== "localhost" && location.hostname !== "127.0.0.1") {
    return;
  }
  const register = () =>
    navigator.serviceWorker
      .register(`${import.meta.env.BASE_URL}sw.js`, { scope: import.meta.env.BASE_URL })
      .then(() => Promise.all([navigator.serviceWorker.ready, assetsLoaded]))
      .then(([registration]) => {
        // On a first visit the compiler downloaded before the service worker
        // was running, so ask it to copy the files into its cache now (from
        // the HTTP cache, normally without another download).
        registration.active?.postMessage({ type: "cache-typst-assets" });
      })
      .catch((e) => console.warn("Service worker registration failed", e));
  if (document.readyState === "complete") register();
  else window.addEventListener("load", register, { once: true });
}
